Gemini Vision module for Tier 4 LLM-based element discovery.
Implements bounding box injection for improved spatial understanding.
"""

import asyncio
import json
import logging
from typing import Any

logger = logging.getLogger(__name__)


class GeminiVision:
    """
    Gemini Vision API client for element discovery and form filling.
    Uses bounding boxes for improved spatial understanding.
    """

    def __init__(self, api_key: str | None = None):
        self.api_key = api_key
        self.model = "gemini-2.0-flash"
        self._client = None

    async def _get_client(self):
        """Lazy initialization of Gemini client."""
        if self._client is None:
            try:
                import google.generativeai as genai
                if self.api_key:
                    genai.configure(api_key=self.api_key)
                self._client = genai.GenerativeModel(self.model)
            except ImportError:
                logger.error("google-generativeai not installed. Run: pip install google-generativeai")
                raise
        return self._client

    async def analyze_screenshot(
        self,
        screenshot: bytes,
        prompt: str,
        max_retries: int = 3
    ) -> dict | None:
        """
        Analyze a screenshot with Gemini Vision.

        Args:
            screenshot: PNG screenshot bytes
            prompt: Question/prompt for the model
            max_retries: Number of retries on failure

        Returns:
            Parsed JSON response or None on failure
        """
        for attempt in range(max_retries):
            try:
                client = await self._get_client()

                # Create image part
                from google.generativeai.types import Part
                image_part = Part(inline_data={
                    "mime_type": "image/png",
                    "data": screenshot
                })

                response = await asyncio.to_thread(
                    client.generate_content,
                    [prompt, image_part]
                )

                if response and response.text:
                    # Try to parse as JSON
                    text = response.text.strip()
                    # Remove markdown code blocks if present
                    if text.startswith("```json"):
                        text = text[7:]
                    if text.startswith("```"):
                        text = text[3:]
                    if text.endswith("```"):
                        text = text[:-3]
                    text = text.strip()

                    try:
                        return json.loads(text)
                    except json.JSONDecodeError:
                        # Return raw text if not JSON
                        return {"text": text}

                return None

            except Exception as e:
                logger.warning(f"Gemini Vision attempt {attempt + 1} failed: {e}")
                if attempt < max_retries - 1:
                    await asyncio.sleep(2 ** attempt)  # Exponential backoff

        return None

    async def inject_bounding_boxes(
        self,
        page,
        selector: str = "button, input, select, textarea, a, [role='button'], [role='checkbox'], [role='radio']"
    ) -> dict[int, dict]:
        """
        Inject numbered bounding boxes into the page for LLM spatial understanding.

        Returns a dict mapping element numbers to their bounding boxes.

        Args:
            page: Playwright page object
            selector: CSS selector for elements to label

        Returns:
            Dict mapping number -> {"x", "y", "width", "height", "tag", "text"}
        """
        js_code = f"""
        () => {{
            const elements = document.querySelectorAll("{selector}");
            const boxes = {{}};
            let num = 1;

            elements.forEach((el) => {{
                // Skip hidden elements
                const rect = el.getBoundingClientRect();
                if (rect.width === 0 || rect.height === 0) return;
                if (window.getComputedStyle(el).visibility === 'hidden') return;

                // Create numbered label overlay
                const label = document.createElement('div');
                label.id = `__bbox_label_${{num}}__`;
                label.style.cssText = `
                    position: absolute;
                    top: ${{rect.top + window.scrollY - 20}}px;
                    left: ${{rect.left + window.scrollX}}px;
                    background: #ff0000;
                    color: white;
                    padding: 2px 6px;
                    font-size: 12px;
                    font-weight: bold;
                    border-radius: 3px;
                    z-index: 999999;
                    pointer-events: none;
                    font-family: monospace;
                `;
                label.textContent = `[${{num}}]`;
                document.body.appendChild(label);

                // Draw border around element
                const border = document.createElement('div');
                border.id = `__bbox_border_${{num}}__`;
                border.style.cssText = `
                    position: absolute;
                    top: ${{rect.top + window.scrollY}}px;
                    left: ${{rect.left + window.scrollX}}px;
                    width: ${{rect.width}}px;
                    height: ${{rect.height}}px;
                    border: 2px solid #ff0000;
                    z-index: 999998;
                    pointer-events: none;
                `;
                document.body.appendChild(border);

                // Store box info
                boxes[num] = {{
                    x: Math.round(rect.left + window.scrollX),
                    y: Math.round(rect.top + window.scrollY),
                    width: Math.round(rect.width),
                    height: Math.round(rect.height),
                    tag: el.tagName.toLowerCase(),
                    text: (el.value || el.textContent || el.getAttribute('aria-label') || '').substring(0, 50)
                }};

                num++;
            }});

            return boxes;
        }}
        """

        try:
            boxes = await page.evaluate(js_code)
            return {int(k): v for k, v in boxes.items()}
        except Exception as e:
            logger.error(f"Failed to inject bounding boxes: {e}")
            return {}

    async def remove_bounding_boxes(self, page):
        """Remove all injected bounding boxes from the page."""
        js_code = """
        () => {
            document.querySelectorAll('[id^="__bbox_"]').forEach(el => el.remove());
        }
        """
        try:
            await page.evaluate(js_code)
        except Exception as e:
            logger.warning(f"Failed to remove bounding boxes: {e}")

    async def find_element_by_description(
        self,
        page,
        description: str,
        screenshot: bytes | None = None
    ) -> dict | None:
        """
        Find an element by natural language description.
        Uses bounding boxes for spatial reference.

        Args:
            page: Playwright page
            description: What element to find (e.g., "Apply button")
            screenshot: Optional pre-captured screenshot

        Returns:
            {"number": int, "coordinates": {"x", "y"}, "selector": str} or None
        """
        # Inject bounding boxes
        boxes = await self.inject_bounding_boxes(page)

        if not boxes:
            logger.warning("No interactive elements found for bounding boxes")
            return None

        # Capture screenshot with boxes
        if screenshot is None:
            screenshot = await page.screenshot()

        # Build element list for prompt
        element_list = "\n".join([
            f"[{num}] <{box['tag']}> {box['text']}"
            for num, box in sorted(boxes.items())
        ])

        prompt = f"""You are analyzing a web page with numbered interactive elements.

Elements on the page:
{element_list}

Question: Which element number is the "{description}"?

Return a JSON object with:
{{"number": <element_number>, "confidence": "high"|"medium"|"low"}}

If no element matches, return {{"number": 0, "confidence": "low"}}"""

        result = await self.analyze_screenshot(screenshot, prompt)

        # Clean up bounding boxes
        await self.remove_bounding_boxes(page)

        if result and "number" in result and result["number"] > 0:
            num = result["number"]
            if num in boxes:
                box = boxes[num]
                return {
                    "number": num,
                    "coordinates": {
                        "x": box["x"] + box["width"] // 2,
                        "y": box["y"] + box["height"] // 2
                    },
                    "selector": f"__bbox_{num}__",  # Can be used to re-locate
                    "bounds": box
                }

        return None

    async def click_element_by_description(
        self,
        page,
        description: str
    ) -> bool:
        """
        Find and click an element by description.

        Args:
            page: Playwright page
            description: Element description

        Returns:
            True if clicked successfully
        """
        result = await self.find_element_by_description(page, description)

        if result and "coordinates" in result:
            coords = result["coordinates"]
            try:
                await page.mouse.click(coords["x"], coords["y"])
                logger.info(f"✅ AI clicked '{description}' at ({coords['x']}, {coords['y']})")
                return True
            except Exception as e:
                logger.error(f"Failed to click at coordinates: {e}")

        return False

    async def fill_form_by_description(
        self,
        page,
        field_descriptions: list[dict]
    ) -> bool:
        """
        Fill multiple form fields using AI.

        Args:
            page: Playwright page
            field_descriptions: List of {"description": str, "value": str}

        Returns:
            True if all fields filled successfully
        """
        # Inject bounding boxes
        boxes = await self.inject_bounding_boxes(page)

        if not boxes:
            logger.warning("No form elements found")
            return False

        screenshot = await page.screenshot()

        # Build element list
        element_list = "\n".join([
            f"[{num}] <{box['tag']}> {box['text']}"
            for num, box in sorted(boxes.items())
        ])

        # Build filling instructions
        fill_instructions = "\n".join([
            f'- "{f["description"]}": type "{f["value"]}"'
            for f in field_descriptions
        ])

        prompt = f"""You are analyzing a web form with numbered fields.

Fields on the page:
{element_list}

Fill the following fields:
{fill_instructions}

Return a JSON list of actions:
[{{"number": <field_number>, "action": "type", "value": "<text>"}}, ...]

If a field cannot be found, skip it.""""""

        result = await self.analyze_screenshot(screenshot, prompt)
        await self.remove_bounding_boxes(page)

        if not result:
            return False

        # Handle both list and dict responses
        actions = result if isinstance(result, list) else result.get("actions", [])

        success_count = 0
        for action in actions:
            num = action.get("number")
            if num and num in boxes:
                box = boxes[num]
                x = box["x"] + box["width"] // 2
                y = box["y"] + box["height"] // 2

                try:
                    # Click to focus
                    await page.mouse.click(x, y)
                    await asyncio.sleep(0.1)

                    # Clear existing value
                    await page.keyboard.press("Control+a")

                    # Type new value
                    if "value" in action:
                        await page.keyboard.type(action["value"])
                        success_count += 1
                except Exception as e:
                    logger.warning(f"Failed to fill field {num}: {e}")

        return success_count == len(field_descriptions)


async def ai_choose_option(
    question: str,
    options: list[str],
    page,
    screenshot: bytes | None = None
) -> str | None:
    """
    Use AI to choose the best option for a select field.

    Args:
        question: The question/label for the select field
        options: Available options
        page: Playwright page (for context if needed)
        screenshot: Optional screenshot

    Returns:
        Best matching option or None
    """
    vision = GeminiVision()

    # Simple fuzzy match first
    from .llm_chain import fuzzy_match
    best = fuzzy_match(question, options, threshold=0.5)
    if best:
        return best

    # Use AI if fuzzy match fails
    prompt = f"""You are filling out a job application form.

Field question: "{question}"
Available options: {json.dumps(options)}

Which option best answers the question? Return only the option text, nothing else.
If unsure, return the first option."""

    result = await vision.analyze_screenshot(
        screenshot or b"",
        prompt
    )

    if result and "text" in result:
        # Clean up the response
        choice = result["text"].strip()
        # Find closest match in options
        for opt in options:
            if choice.lower() in opt.lower() or opt.lower() in choice.lower():
                return opt
        return choice

    return None


# Convenience function for importing
__all__ = [
    "GeminiVision",
    "ai_choose_option",
]
